/**
 * Serves every Expo API route (src/app/api) from the web app, unchanged. The table is
 * generated by scripts/web-routes.ts; each handler takes (Request, params) like Expo's.
 */
import { routes, type RouteModule } from '@web/lib/routes.generated';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300;

type Ctx = { params: Promise<{ path: string[] }> };

async function dispatch(method: keyof RouteModule, req: Request, ctx: Ctx) {
  const { path } = await ctx.params;
  const joined = path.map(decodeURIComponent).join('/');
  for (const r of routes) {
    const m = joined.match(r.re);
    if (!m) continue;
    const mod = await r.load();
    const fn = mod[method];
    if (!fn) return Response.json({ error: 'Method not allowed.' }, { status: 405 });
    const params = Object.fromEntries(r.params.map((p, i) => [p, m[i + 1]]));
    return fn(req, params);
  }
  return Response.json({ error: 'Not found.' }, { status: 404 });
}

export const GET = (req: Request, ctx: Ctx) => dispatch('GET', req, ctx);
export const POST = (req: Request, ctx: Ctx) => dispatch('POST', req, ctx);
export const PUT = (req: Request, ctx: Ctx) => dispatch('PUT', req, ctx);
export const PATCH = (req: Request, ctx: Ctx) => dispatch('PATCH', req, ctx);
export const DELETE = (req: Request, ctx: Ctx) => dispatch('DELETE', req, ctx);
